 3→
 4→const firebaseConfig = {
 5→  apiKey: process.env.NEXT_PUBLIC_FIREBASE_API_KEY,
 6→  authDomain: process.env.NEXT_PUBLIC_FIREBASE_AUTH_DOMAIN,
 7→  projectId: process.env.NEXT_PUBLIC_FIREBASE_PROJECT_ID,
