  1→'use client';
  2→
  3→import { useEffect, useState } from 'react';
  4→import { collection, getDocs, query, orderBy } from 'firebase/firestore';
  5→import { db } from '../../lib/firebase';
  6→import { Card, CardContent, CardHeader, CardTitle } from '@modules/shared/card';
  7→import { Button } from '@modules/shared/button';
  8→import {
  9→  Download,
 10→  Users,
 11→  Mail,
 12→  Phone,
 13→  Calendar,
 14→  Heart,
 15→  Sparkles,
 16→  FileText,
 17→} from 'lucide-react';
 18→import { toast } from 'sonner';
 19→
 20→interface Guest {
 21→  ime: string;
 22→  prezime: string;
 23→  email?: string;
 24→  telefon?: string;
 25→}
 26→
 27→interface GuestEntry {
 28→  id: string;
 29→  gosti: Guest[];
 30→  napomena?: string;
 31→  createdAt: string;
 32→}
 33→
 34→export default function GostiPage() {
 35→  const [entries, setEntries] = useState<GuestEntry[]>([]);
 36→  const [loading, setLoading] = useState(true);
 37→  const [totalGuests, setTotalGuests] = useState(0);
 38→
 39→  useEffect(() => {
 40→    fetchGuests();
 41→  }, []);
 42→
 43→  const fetchGuests = async () => {
 44→    try {
 45→      const q = query(
 46→        collection(db, 'wedding-guests'),
 47→        orderBy('createdAt', 'desc'),
 48→      );
 49→      const querySnapshot = await getDocs(q);
 50→
 51→      const data: GuestEntry[] = [];
 52→      let guestCount = 0;
 53→
 54→      querySnapshot.forEach((doc) => {
 55→        const entry = { id: doc.id, ...doc.data() } as GuestEntry;
 56→        data.push(entry);
 57→        guestCount += entry.gosti.length;
 58→      });
 59→
 60→      setEntries(data);
 61→      setTotalGuests(guestCount);
 62→    } catch (error) {
 63→      console.error('Error fetching guests:', error);
 64→      toast.error('Greška pri učitavanju gostiju');
 65→    } finally {
 66→      setLoading(false);
 67→    }
 68→  };
 69→
 70→  const exportToExcel = () => {
 71→    try {
 72→      // Create CSV content
 73→      let csvContent = '\uFEFF'; // UTF-8 BOM for proper encoding
 74→      csvContent += 'Ime,Prezime,Email,Telefon,Napomena,Datum prijave\n';
 75→
 76→      entries.forEach((entry) => {
 77→        const date = new Date(entry.createdAt).toLocaleDateString('hr-HR');
 78→        entry.gosti.forEach((gost) => {
 79→          const row = [
 80→            gost.ime,
 81→            gost.prezime,
 82→            gost.email || '',
 83→            gost.telefon || '',
 84→            entry.napomena || '',
 85→            date,
 86→          ]
 87→            .map((field) => `"${field}"`)
 88→            .join(',');
 89→          csvContent += row + '\n';
 90→        });
 91→      });
 92→
 93→      // Create blob and download
 94→      const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
 95→      const link = document.createElement('a');
 96→      const url = URL.createObjectURL(blob);
 97→
 98→      link.setAttribute('href', url);
 99→      link.setAttribute(
100→        'download',
101→        `vjenčanje-gosti-${new Date().toISOString().split('T')[0]}.csv`,
102→      );
103→      link.style.visibility = 'hidden';
104→
105→      document.body.appendChild(link);
106→      link.click();
107→      document.body.removeChild(link);
108→
109→      toast.success('CSV datoteka preuzeta!');
110→    } catch (error) {
111→      console.error('Error exporting:', error);
112→      toast.error('Greška pri exportu');
113→    }
114→  };
115→
116→  if (loading) {
117→    return (
118→      <div className="min-h-screen bg-linear-to-br from-[#fdfcfb] via-white to-[#f8f9fa] flex items-center justify-center">
119→        <div className="text-center space-y-4">
120→          <div className="w-16 h-16 border-4 border-priamry border-t-transparent rounded-full animate-spin mx-auto" />
121→          <div className="text-3xl text-priamry font-serif">
122→            Učitavanje...
123→          </div>
124→        </div>
125→      </div>
126→    );
127→  }
128→
129→  return (
130→    <div className="min-h-screen bg-linear-to-br from-[#fdfcfb] via-white to-[#f8f9fa] relative overflow-hidden">
131→      {/* Decorative background */}
132→      <div className="absolute inset-0 overflow-hidden pointer-events-none">
133→        <div className="absolute top-20 left-10 w-72 h-72 bg-priamry/5 rounded-full blur-3xl animate-pulse" />
134→        <div
135→          className="absolute bottom-20 right-10 w-96 h-96 bg-secondary/5 rounded-full blur-3xl animate-pulse"
136→          style={{ animationDelay: '1s' }}
137→        />
138→      </div>
139→
140→      <div className="container mx-auto px-4 py-8 max-w-7xl relative z-10">
141→        {/* Header */}
142→        <div className="text-center mb-12 space-y-6">
143→          <h1 className="text-5xl md:text-7xl bg-linear-to-r from-priamry to-[#6a9fc2] bg-clip-text text-transparent font-cursive">
144→            Popis Gostiju
145→          </h1>
146→          <div className="flex items-center justify-center gap-3">
147→            <div className="h-px flex-1 max-w-24 bg-linear-to-r from-transparent via-secondary to-secondary" />
148→            <Heart
149→              className="w-6 h-6 text-secondary animate-pulse"
150→              fill="#ADCD78"
151→            />
152→            <div className="h-px flex-1 max-w-24 bg-linear-to-l from-transparent via-secondary to-secondary" />
153→          </div>
154→          <p className="text-2xl text-priamry font-serif">Elisa & Matko</p>
155→        </div>
156→
157→        {/* Stats Cards */}
158→        <div className="grid md:grid-cols-3 gap-6 mb-10">
159→          <Card className="border-2 border-priamry/30 shadow-xl hover:shadow-2xl transition-all duration-300 hover:scale-105 bg-white/95 backdrop-blur-sm overflow-hidden group">
160→            <div className="absolute inset-0 bg-linear-to-br from-priamry/5 to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-300" />
161→            <CardContent className="pt-8 pb-8 relative z-10">
162→              <div className="flex items-center justify-between">
163→                <div>
164→                  <p className="text-sm font-medium text-priamry/70 mb-2 font-serif">
165→                    Ukupno gostiju
166→                  </p>
167→                  <p className="text-5xl font-bold text-priamry font-serif">
168→                    {totalGuests}
169→                  </p>
170→                </div>
171→                <div className="w-16 h-16 rounded-full bg-secondary/10 flex items-center justify-center group-hover:scale-110 transition-transform duration-300">
172→                  <Users className="w-8 h-8 text-secondary" />
173→                </div>
174→              </div>
175→            </CardContent>
176→          </Card>
177→
178→          <Card className="border-2 border-priamry/30 shadow-xl hover:shadow-2xl transition-all duration-300 hover:scale-105 bg-white/95 backdrop-blur-sm overflow-hidden group">
179→            <div className="absolute inset-0 bg-linear-to-br from-priamry/5 to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-300" />
180→            <CardContent className="pt-8 pb-8 relative z-10">
181→              <div className="flex items-center justify-between">
182→                <div>
183→                  <p className="text-sm font-medium text-priamry/70 mb-2 font-serif">
184→                    Prijave
185→                  </p>
186→                  <p className="text-5xl font-bold text-priamry font-serif">
187→                    {entries.length}
188→                  </p>
189→                </div>
190→                <div className="w-16 h-16 rounded-full bg-secondary/10 flex items-center justify-center group-hover:scale-110 transition-transform duration-300">
191→                  <Calendar className="w-8 h-8 text-secondary" />
192→                </div>
193→              </div>
194→            </CardContent>
195→          </Card>
196→
197→          <Card className="border-2 border-secondary/30 shadow-xl hover:shadow-2xl transition-all duration-300 bg-linear-to-br from-secondary/5 to-white/95 backdrop-blur-sm overflow-hidden group">
198→            <CardContent className="pt-8 pb-8">
199→              <div className="flex items-center justify-center h-full">
200→                <Button
201→                  onClick={exportToExcel}
202→                  className="gap-3 w-full h-14 bg-linear-to-r from-secondary to-[#9ab86a] hover:from-[#9ab86a] hover:to-[#8aa75b] text-white shadow-lg hover:shadow-xl transition-all duration-300 text-lg rounded-xl group-hover:scale-105">
203→                  <Download className="w-5 h-5" />
204→                  Preuzmi CSV
205→                  <Sparkles className="w-4 h-4" />
206→                </Button>
207→              </div>
208→            </CardContent>
209→          </Card>
210→        </div>
211→
212→        {/* Guest Entries List */}
213→        <div className="space-y-6">
214→          {entries.length === 0 ? (
215→            <Card className="border-2 border-priamry/30 shadow-xl bg-white/95 backdrop-blur-sm">
216→              <CardContent className="py-16">
217→                <div className="text-center space-y-4">
218→                  <div className="w-20 h-20 rounded-full bg-priamry/10 flex items-center justify-center mx-auto">
219→                    <Users className="w-10 h-10 text-priamry" />
220→                  </div>
221→                  <p className="text-2xl text-priamry font-serif">
222→                    Još nema prijava
223→                  </p>
224→                </div>
225→              </CardContent>
226→            </Card>
227→          ) : (
228→            entries.map((entry, entryIndex) => (
229→              <Card
230→                key={entry.id}
231→                className="border-2 border-priamry/30 shadow-xl hover:shadow-2xl transition-all duration-300 bg-white/95 backdrop-blur-sm overflow-hidden group"
232→                style={{
233→                  animationDelay: `${entryIndex * 50}ms`,
234→                }}>
235→                <CardHeader className="pb-4 bg-linear-to-r from-[#fdfcfb] to-white border-b-2 border-priamry/10">
236→                  <div className="flex items-center justify-between flex-wrap gap-4">
237→                    <CardTitle className="text-2xl md:text-3xl flex items-center gap-3 text-priamry font-serif">
238→                      <div className="w-10 h-10 rounded-full bg-priamry/10 flex items-center justify-center">
239→                        <Users className="w-5 h-5" />
240→                      </div>
241→                      Prijava - {entry.gosti.length}{' '}
242→                      {entry.gosti.length === 1 ? 'gost' : 'gostiju'}
243→                    </CardTitle>
244→                    <div className="flex items-center gap-2 text-sm text-priamry/70 bg-priamry/5 px-4 py-2 rounded-full">
245→                      <Calendar className="w-4 h-4" />
246→                      {new Date(entry.createdAt).toLocaleString('hr-HR', {
247→                        day: '2-digit',
248→                        month: '2-digit',
249→                        year: 'numeric',
250→                        hour: '2-digit',
251→                        minute: '2-digit',
252→                      })}
253→                    </div>
254→                  </div>
255→                </CardHeader>
256→                <CardContent className="pt-6 pb-6">
257→                  <div className="space-y-4">
258→                    {entry.gosti.map((gost, index) => (
259→                      <div
260→                        key={index}
261→                        className="p-5 rounded-xl border-2 border-secondary/20 bg-linear-to-br from-[#fdfcfb] to-white hover:shadow-md transition-all duration-200 hover:border-secondary/40 group">
262→                        <div className="flex items-start gap-3">
263→                          <div className="w-8 h-8 rounded-full bg-priamry/10 flex items-center justify-center flex-shrink-0 text-priamry font-bold group-hover:bg-priamry group-hover:text-white transition-colors duration-200">
264→                            {index + 1}
265→                          </div>
266→                          <div className="flex-1">
267→                            <h4 className="font-semibold text-lg mb-2 text-priamry font-serif">
268→                              {gost.ime} {gost.prezime}
269→                            </h4>
270→                            <div className="space-y-1 text-sm">
271→                              {gost.email && (
272→                                <div className="flex items-center gap-2 text-gray-600">
273→                                  <Mail className="w-4 h-4 text-priamry" />
274→                                  <span>{gost.email}</span>
275→                                </div>
276→                              )}
277→                              {gost.telefon && (
278→                                <div className="flex items-center gap-2 text-gray-600">
279→                                  <Phone className="w-4 h-4 text-priamry" />
280→                                  <span>{gost.telefon}</span>
281→                                </div>
282→                              )}
283→                            </div>
284→                          </div>
285→                        </div>
286→                      </div>
287→                    ))}
288→                  </div>
289→
290→                  {entry.napomena && (
291→                    <div className="mt-6 p-5 rounded-xl border-2 border-secondary/20 bg-linear-to-br from-secondary/5 to-white">
292→                      <h4 className="font-semibold mb-3 text-lg flex items-center gap-2 text-priamry font-serif">
293→                        <FileText className="w-5 h-5" />
294→                        Napomena:
295→                      </h4>
296→                      <p className="text-sm text-gray-700 leading-relaxed">
297→                        {entry.napomena}
298→                      </p>
299→                    </div>
300→                  )}
301→                </CardContent>
302→              </Card>
303→            ))
304→          )}
305→        </div>
306→      </div>
307→    </div>
308→  );
309→}
310→
